CREATE TABLE IF NOT EXISTS "roles" (
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(50) NOT NULL UNIQUE,
	"description" TEXT,
	"created_at" TIMESTAMP,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "users" (
	"id" UUID,
	"role_id" BIGINT NOT NULL,
	"username" VARCHAR(100) NOT NULL UNIQUE,
	"password_hash" TEXT NOT NULL,
	"full_name" VARCHAR(150) NOT NULL,
	"email" VARCHAR(150),
	"phone" VARCHAR(30),
	"is_active" BOOLEAN,
	"last_login" TIMESTAMP,
	"created_at" TIMESTAMP,
	"updated_at" TIMESTAMP,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "licenses" (
	"id" UUID,
	"user_id" UUID NOT NULL UNIQUE,
	"license_number" VARCHAR(100) NOT NULL UNIQUE,
	"issued_by" VARCHAR(150),
	"issued_date" DATE,
	"expired_date" DATE,
	"status" VARCHAR(30),
	"created_at" TIMESTAMP,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "locations" (
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(150),
	"city" VARCHAR(100),
	"province" VARCHAR(100),
	"latitude" DECIMAL,
	"longitude" DECIMAL,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "balloons" (
	"id" UUID,
	"serial_number" VARCHAR(100),
	"balloon_name" VARCHAR(150),
	"capacity" DECIMAL,
	"max_altitude" DECIMAL,
	"status" VARCHAR(50),
	"created_at" TIMESTAMP,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "mission_status" (
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(50),
	"description" TEXT,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "mission_roles" (
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(100),
	"description" TEXT,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "flight_simulations" (
	"id" UUID,
	"simulation_name" VARCHAR(150),
	"payload_weight" DECIMAL,
	"helium_volume" DECIMAL,
	"flight_altitude" DECIMAL,
	"estimated_duration" INTEGER,
	"wind_speed" DECIMAL,
	"gust_speed" DECIMAL,
	"visibility" DECIMAL,
	"rainfall" DECIMAL,
	"temperature" DECIMAL,
	"go_no_go" BOOLEAN,
	"remarks" TEXT,
	"created_by" UUID,
	"created_at" TIMESTAMP,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "flight_missions" (
	"id" UUID,
	"simulation_id" UUID NOT NULL,
	"mission_code" VARCHAR(100) NOT NULL UNIQUE,
	"mission_name" VARCHAR(150),
	"description" TEXT,
	"location_id" BIGINT,
	"balloon_id" UUID,
	"status_id" BIGINT,
	"created_by" UUID,
	"created_at" TIMESTAMP,
	"updated_at" TIMESTAMP,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "mission_members" (
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	"mission_id" UUID,
	"user_id" UUID,
	"mission_role_id" BIGINT,
	"created_at" TIMESTAMP,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "flight_information" (
	"id" UUID,
	"mission_id" UUID NOT NULL UNIQUE,
	"mission_leader" VARCHAR(150),
	"operator_id" UUID,
	"takeoff_time" TIMESTAMP,
	"landing_time" TIMESTAMP,
	"duration" INTEGER,
	"max_altitude" DECIMAL,
	"cable_length" DECIMAL,
	"weather" VARCHAR(100),
	"remarks" TEXT,
	"created_at" TIMESTAMP,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "media" (
	"id" UUID,
	"flight_information_id" UUID NOT NULL,
	"media_type" VARCHAR(20),
	"original_filename" VARCHAR(255),
	"stored_filename" VARCHAR(255),
	"mime_type" VARCHAR(100),
	"file_size" BIGINT,
	"uploaded_by" UUID,
	"uploaded_at" TIMESTAMP,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "ai_job_types" (
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(100) NOT NULL UNIQUE,
	"description" TEXT,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "ai_models" (
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	"model_name" VARCHAR(100) NOT NULL,
	"version" VARCHAR(50),
	"framework" VARCHAR(50),
	"description" TEXT,
	"created_at" TIMESTAMP,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "ai_jobs" (
	"id" UUID,
	"media_id" UUID NOT NULL,
	"job_type_id" BIGINT NOT NULL,
	"model_id" BIGINT NOT NULL,
	"status" VARCHAR(30),
	"output_filename" VARCHAR(255),
	"thumbnail_filename" VARCHAR(255),
	"processing_time" DECIMAL,
	"started_at" TIMESTAMP,
	"finished_at" TIMESTAMP,
	"created_by" UUID,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "ai_frame_results" (
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	"job_id" UUID NOT NULL,
	"frame_number" INTEGER,
	"timestamp_ms" BIGINT,
	"person_count" INTEGER,
	"vehicle_count" INTEGER,
	"crowd_count" INTEGER,
	"processing_time" DECIMAL,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "audit_modules" (
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	"name" VARCHAR(100) NOT NULL UNIQUE,
	"description" TEXT,
	PRIMARY KEY("id")
);




CREATE TABLE IF NOT EXISTS "audit_logs" (
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	"user_id" UUID,
	"module_id" BIGINT,
	"action" VARCHAR(50),
	"entity" VARCHAR(100),
	"entity_id" UUID,
	"description" TEXT,
	"ip_address" VARCHAR(50),
	"user_agent" TEXT,
	"status" VARCHAR(30),
	"created_at" TIMESTAMP,
	PRIMARY KEY("id")
);



ALTER TABLE "users"
ADD FOREIGN KEY("role_id") REFERENCES "roles"("id")
ON UPDATE NO ACTION ON DELETE NO ACTION;
